import torch


def run(input, mask, scale):
    # aten._masked_scale has no CPU backend; compute the reference manually,
    # mirroring tests/test_masked_scale.py.
    return torch.where(
        mask.to(torch.bool), input * scale, torch.zeros_like(input)
    )


def gen_inputs(ctx, device):
    # mask is a uint8 tensor of 0/1 values (torch.randint(0, 2, ...)), matching
    # both the correctness test and the benchmark input generator. Generic
    # random uint8 would be nonzero almost everywhere and change the semantics.
    mask_shape = ctx["mask__shape"]
    mask = torch.randint(0, 2, tuple(mask_shape), dtype=torch.uint8, device=device)
    return {"mask": mask}
